 32	const RADIAN = Math.PI / 180;
 33	
 34	interface LabelLayout {
 35	    label: ZRText
 36	    labelLine: Polyline
 37	    position: PieSeriesOption['label']['position']
 38	    len: number
 39	    len2: number
 40	    minTurnAngle: number
 41	    maxSurfaceAngle: number
 42	    surfaceNormal: Point
 43	    linePoints: VectorArray[]
 44	    textAlign: HorizontalAlign
 45	    labelDistance: number
 46	    labelAlignTo: PieSeriesOption['label']['alignTo']
 47	    edgeDistance: number
 48	    bleedMargin: PieSeriesOption['label']['bleedMargin']
 49	    rect: BoundingRect
 50	    /**
 51	     * user-set style.width.
 52	     * This is useful because label.style.width might be changed
 53	     * by constrainTextWidth.
 54	     */
 55	    labelStyleWidth: number
 56	    unconstrainedWidth: number
 57	    targetTextWidth?: number
 58	}
 59	
 60	function adjustSingleSide(
 61	    list: LabelLayout[],
 62	    cx: number,
 63	    cy: number,
 64	    r: number,
 65	    dir: -1 | 1,
 66	    viewWidth: number,
 67	    viewHeight: number,
 68	    viewLeft: number,
 69	    viewTop: number,
 70	    farthestX: number
 71	) {
 72	    if (list.length < 2) {
 73	        return;
 74	    }
 75	
 76	    interface SemiInfo {
 77	        list: LabelLayout[]
 78	        rB: number
 79	        maxY: number
 80	    };
 81	
 82	    function recalculateXOnSemiToAlignOnEllipseCurve(semi: SemiInfo) {
 83	        const rB = semi.rB;
 84	        const rB2 = rB * rB;
 85	        for (let i = 0; i < semi.list.length; i++) {
 86	            const item = semi.list[i];
 87	            const dy = Math.abs(item.label.y - cy);
 88	            // horizontal r is always same with original r because x is not changed.
 89	            const rA = r + item.len;
 90	            const rA2 = rA * rA;
 91	            // Use ellipse implicit function to calculate x
 92	            // `dy` may be larger than `rB` when the labels are dense and have
 93	            // been shifted out of the ellipse on the y axis. In that case the
 94	            // radicand would be negative, which makes `dx` (and thus the label
 95	            // position) NaN and the label be dropped afterwards. Clamp it to
 96	            // keep the label on the ellipse (x is not moved outwards then).
 97	            const dx = Math.sqrt(Math.max(1 - dy * dy / rB2, 0) * rA2);
 98	            const newX = cx + (dx + item.len2) * dir;
 99	            const deltaX = newX - item.label.x;
100	            const newTargetWidth = item.targetTextWidth - deltaX * dir;
101	            // text x is changed, so need to recalculate width.
102	            constrainTextWidth(item, newTargetWidth, true);
103	            item.label.x = newX;
104	        }
105	    }
106	
107	    // Adjust X based on the shifted y. Make tight labels aligned on an ellipse curve.
108	    function recalculateX(items: LabelLayout[]) {
109	        // Extremes of
110	        const topSemi = { list: [], maxY: 0} as SemiInfo;
111	        const bottomSemi = { list: [], maxY: 0 } as SemiInfo;
112	
113	        for (let i = 0; i < items.length; i++) {
114	            if (items[i].labelAlignTo !== 'none') {
115	                continue;
116	            }
117	            const item = items[i];
118	            const semi = item.label.y > cy ? bottomSemi : topSemi;
119	            const dy = Math.abs(item.label.y - cy);
120	            if (dy >= semi.maxY) {
121	                const dx = item.label.x - cx - item.len2 * dir;
122	                // horizontal r is always same with original r because x is not changed.
123	                const rA = r + item.len;
124	                // Canculate rB based on the topest / bottemest label.
125	                const rB = Math.abs(dx) < rA
126	                    ? Math.sqrt(dy * dy / (1 - dx * dx / rA / rA))
127	                    : rA;
128	                semi.rB = rB;
129	                semi.maxY = dy;
130	            }
131	            semi.list.push(item);
132	        }
133	
134	        recalculateXOnSemiToAlignOnEllipseCurve(topSemi);
135	        recalculateXOnSemiToAlignOnEllipseCurve(bottomSemi);
136	    }
137	
138	    const len = list.length;
139	    for (let i = 0; i < len; i++) {
140	        if (list[i].position === 'outer' && list[i].labelAlignTo === 'labelLine') {
141	            const dx = list[i].label.x - farthestX;
142	            list[i].linePoints[1][0] += dx;
143	            list[i].label.x = farthestX;
144	        }
145	    }
146	
147	    if (shiftLayoutOnY(list, viewTop, viewTop + viewHeight)) {
148	        recalculateX(list);
149	    }
150	}
