152	function avoidOverlap(
153	    labelLayoutList: LabelLayout[],
154	    cx: number,
155	    cy: number,
156	    r: number,
157	    viewWidth: number,
158	    viewHeight: number,
159	    viewLeft: number,
160	    viewTop: number
161	) {
162	    const leftList = [];
163	    const rightList = [];
164	    let leftmostX = Number.MAX_VALUE;
165	    let rightmostX = -Number.MAX_VALUE;
166	    for (let i = 0; i < labelLayoutList.length; i++) {
167	        const label = labelLayoutList[i].label;
168	        if (isPositionCenter(labelLayoutList[i])) {
169	            continue;
170	        }
171	        if (label.x < cx) {
172	            leftmostX = Math.min(leftmostX, label.x);
173	            leftList.push(labelLayoutList[i]);
174	        }
175	        else {
176	            rightmostX = Math.max(rightmostX, label.x);
177	            rightList.push(labelLayoutList[i]);
178	        }
179	    }
180	
181	    for (let i = 0; i < labelLayoutList.length; i++) {
182	        const layout = labelLayoutList[i];
183	        if (!isPositionCenter(layout) && layout.linePoints) {
184	            if (layout.labelStyleWidth != null) {
185	                continue;
186	            }
187	
188	            const label = layout.label;
189	            const linePoints = layout.linePoints;
190	
191	            let targetTextWidth;
192	            if (layout.labelAlignTo === 'edge') {
193	                if (label.x < cx) {
194	                    targetTextWidth = linePoints[2][0] - layout.labelDistance
195	                            - viewLeft - layout.edgeDistance;
196	                }
197	                else {
198	                    targetTextWidth = viewLeft + viewWidth - layout.edgeDistance
199	                            - linePoints[2][0] - layout.labelDistance;
200	                }
201	            }
202	            else if (layout.labelAlignTo === 'labelLine') {
203	                if (label.x < cx) {
204	                    targetTextWidth = leftmostX - viewLeft - layout.bleedMargin;
205	                }
206	                else {
207	                    targetTextWidth = viewLeft + viewWidth - rightmostX - layout.bleedMargin;
208	                }
209	            }
210	            else {
211	                if (label.x < cx) {
212	                    targetTextWidth = label.x - viewLeft - layout.bleedMargin;
213	                }
214	                else {
215	                    targetTextWidth = viewLeft + viewWidth - label.x - layout.bleedMargin;
216	                }
217	            }
218	            layout.targetTextWidth = targetTextWidth;
219	
220	            constrainTextWidth(layout, targetTextWidth);
221	        }
222	    }
223	
224	    adjustSingleSide(rightList, cx, cy, r, 1, viewWidth, viewHeight, viewLeft, viewTop, rightmostX);
225	    adjustSingleSide(leftList, cx, cy, r, -1, viewWidth, viewHeight, viewLeft, viewTop, leftmostX);
226	
227	    for (let i = 0; i < labelLayoutList.length; i++) {
228	        const layout = labelLayoutList[i];
229	        if (!isPositionCenter(layout) && layout.linePoints) {
230	            const label = layout.label;
231	            const linePoints = layout.linePoints;
232	            const isAlignToEdge = layout.labelAlignTo === 'edge';
233	            const padding = label.style.padding as number[];
234	            const paddingH = padding ? padding[1] + padding[3] : 0;
235	            // textRect.width already contains paddingH if bgColor is set
236	            const extraPaddingH = label.style.backgroundColor ? 0 : paddingH;
237	            const realTextWidth = layout.rect.width + extraPaddingH;
238	            const dist = linePoints[1][0] - linePoints[2][0];
239	            if (isAlignToEdge) {
240	                if (label.x < cx) {
241	                    linePoints[2][0] = viewLeft + layout.edgeDistance + realTextWidth + layout.labelDistance;
242	                }
243	                else {
244	                    linePoints[2][0] = viewLeft + viewWidth - layout.edgeDistance
245	                            - realTextWidth - layout.labelDistance;
246	                }
247	            }
248	            else {
249	                if (label.x < cx) {
250	                    linePoints[2][0] = label.x + layout.labelDistance;
251	                }
252	                else {
253	                    linePoints[2][0] = label.x - layout.labelDistance;
254	                }
255	                linePoints[1][0] = linePoints[2][0] + dist;
256	            }
257	            linePoints[1][1] = linePoints[2][1] = label.y;
258	        }
259	    }
260	}
261	
262	/**
263	 * Set max width of each label, and then wrap each label to the max width.
264	 *
265	 * @param layout label layout
266	 * @param availableWidth max width for the label to display
267	 * @param forceRecalculate recaculate the text layout even if the current width
268	 * is smaller than `availableWidth`. This is useful when the text was previously
269	 * wrapped by calling `constrainTextWidth` but now `availableWidth` changed, in
270	 * which case, previous wrapping should be redo.
271	 */
272	function constrainTextWidth(
273	    layout: LabelLayout,
274	    availableWidth: number,
275	    forceRecalculate: boolean = false
276	) {
277	    if (layout.labelStyleWidth != null) {
278	        // User-defined style.width has the highest priority.
279	        return;
280	    }
281	
282	    const label = layout.label;
283	    const style = label.style;
284	    const textRect = layout.rect;
285	    const bgColor = style.backgroundColor;
286	    const padding = style.padding as number[];
287	    const paddingH = padding ? padding[1] + padding[3] : 0;
288	    const overflow = style.overflow;
289	
290	    // textRect.width already contains paddingH if bgColor is set
291	    const oldOuterWidth = textRect.width + (bgColor ? 0 : paddingH);
292	    if (availableWidth < oldOuterWidth || forceRecalculate) {
293	        const oldHeight = textRect.height;
294	        if (overflow && overflow.match('break')) {
295	            // Temporarily set background to be null to calculate
296	            // the bounding box without background.
297	            label.setStyle('backgroundColor', null);
298	            // Set constraining width
299	            label.setStyle('width', availableWidth - paddingH);
300	
301	            // This is the real bounding box of the text without padding.
302	            const innerRect = label.getBoundingRect();
303	
304	            label.setStyle('width', Math.ceil(innerRect.width));
305	            label.setStyle('backgroundColor', bgColor);
306	        }
307	        else {
308	            const availableInnerWidth = availableWidth - paddingH;
309	            const newWidth = availableWidth < oldOuterWidth
310	                // Current text is too wide, use `availableWidth` as max width.
311	                ? availableInnerWidth
312	                : (
313	                    // Current available width is enough, but the text may have
314	                    // already been wrapped with a smaller available width.
315	                    forceRecalculate
316	                        ? (availableInnerWidth > layout.unconstrainedWidth
317	                            // Current available is larger than text width,
318	                            // so don't constrain width (otherwise it may have
319	                            // empty space in the background).
320	                            ? null
321	                            // Current available is smaller than text width, so
322	                            // use the current available width as constraining
323	                            // width.
324	                            : availableInnerWidth
325	                        )
326	                    // Current available width is enough, so no need to
327	                    // constrain.
328	                    : null
329	                );
330	            label.setStyle('width', newWidth);
331	        }
332	
333	        const newRect = label.getBoundingRect();
334	        textRect.width = newRect.width;
335	        const margin = (label.style.margin || 0) + 2.1;
336	        textRect.height = newRect.height + margin;
337	        textRect.y -= (textRect.height - oldHeight) / 2;
338	    }
339	}
340	
341	function isPositionCenter(sectorShape: LabelLayout) {
342	    // Not change x for center label
343	    return sectorShape.position === 'center';
344	}
345	
346	export default function pieLabelLayout(
347	    seriesModel: PieSeriesModel
348	) {
349	    const data = seriesModel.getData();
350	    const labelLayoutList: LabelLayout[] = [];
351	    let cx;
352	    let cy;
353	    let hasLabelRotate = false;
354	    const minShowLabelRadian = (seriesModel.get('minShowLabelAngle') || 0) * RADIAN;
355	
356	    const viewRect = data.getLayout('viewRect') as RectLike;
357	    const r = data.getLayout('r') as number;
358	    const viewWidth = viewRect.width;
359	    const viewLeft = viewRect.x;
360	    const viewTop = viewRect.y;
361	    const viewHeight = viewRect.height;
362	
363	    function setNotShow(el: {ignore: boolean}) {
364	        el.ignore = true;
365	    }
366	
367	    function isLabelShown(label: ZRText) {
368	        if (!label.ignore) {
369	            return true;
370	        }
371	        for (const key in label.states) {
372	            if (label.states[key].ignore === false) {
373	                return true;
374	            }
375	        }
376	        return false;
377	    }
378	
379	    data.each(function (idx) {
380	        const sector = data.getItemGraphicEl(idx) as Sector;
381	        const sectorShape = sector.shape;
382	        const label = sector.getTextContent();
383	        const labelLine = sector.getTextGuideLine();
384	
385	        const itemModel = data.getItemModel<PieDataItemOption>(idx);
386	        const labelModel = itemModel.getModel('label');
387	        // Use position in normal or emphasis
388	        const labelPosition = labelModel.get('position') || itemModel.get(['emphasis', 'label', 'position']);
389	        const labelDistance = labelModel.get('distanceToLabelLine');
390	        const labelAlignTo = labelModel.get('alignTo');
391	        const edgeDistance = parsePercent(labelModel.get('edgeDistance'), viewWidth);
392	        const bleedMargin = labelModel.get('bleedMargin');
393	
394	        const labelLineModel = itemModel.getModel('labelLine');
395	        let labelLineLen = labelLineModel.get('length');
396	        labelLineLen = parsePercent(labelLineLen, viewWidth);
397	        let labelLineLen2 = labelLineModel.get('length2');
398	        labelLineLen2 = parsePercent(labelLineLen2, viewWidth);
399	
400	        if (Math.abs(sectorShape.endAngle - sectorShape.startAngle) < minShowLabelRadian) {
401	            each(label.states, setNotShow);
402	            label.ignore = true;
403	            if (labelLine) {
404	                each(labelLine.states, setNotShow);
405	                labelLine.ignore = true;
406	            }
407	            return;
408	        }
409	
410	        if (!isLabelShown(label)) {
411	            return;
412	        }
413	
414	        const midAngle = (sectorShape.startAngle + sectorShape.endAngle) / 2;
415	        const nx = Math.cos(midAngle);
416	        const ny = Math.sin(midAngle);
417	
418	        let textX;
419	        let textY;
420	        let linePoints;
421	        let textAlign: ZRTextAlign;
422	
423	        cx = sectorShape.cx;
424	        cy = sectorShape.cy;
425	
426	
427	        const isLabelInside = labelPosition === 'inside' || labelPosition === 'inner';
428	        if (labelPosition === 'center') {
429	            textX = sectorShape.cx;
430	            textY = sectorShape.cy;
431	            textAlign = 'center';
432	        }
433	        else {
434	            const x1 = (isLabelInside ? (sectorShape.r + sectorShape.r0) / 2 * nx : sectorShape.r * nx) + cx;
435	            const y1 = (isLabelInside ? (sectorShape.r + sectorShape.r0) / 2 * ny : sectorShape.r * ny) + cy;
436	
437	            textX = x1 + nx * 3;
438	            textY = y1 + ny * 3;
439	
440	            if (!isLabelInside) {
441	                // For roseType
442	                const x2 = x1 + nx * (labelLineLen + r - sectorShape.r);
443	                const y2 = y1 + ny * (labelLineLen + r - sectorShape.r);
444	                const x3 = x2 + ((nx < 0 ? -1 : 1) * labelLineLen2);
445	                const y3 = y2;
446	
447	                if (labelAlignTo === 'edge') {
448	                    // Adjust textX because text align of edge is opposite
449	                    textX = nx < 0
450	                        ? viewLeft + edgeDistance
451	                        : viewLeft + viewWidth - edgeDistance;
452	                }
453	                else {
454	                    textX = x3 + (nx < 0 ? -labelDistance : labelDistance);
455	                }
456	                textY = y3;
457	                linePoints = [[x1, y1], [x2, y2], [x3, y3]];
458	            }
459	
460	            textAlign = isLabelInside
461	                ? 'center'
462	                : (labelAlignTo === 'edge'
463	                    ? (nx > 0 ? 'right' : 'left')
464	                    : (nx > 0 ? 'left' : 'right'));
465	        }
466	
467	        const PI = Math.PI;
468	        let labelRotate = 0;
469	        const rotate = labelModel.get('rotate');
470	        if (isNumber(rotate)) {
471	            labelRotate = rotate * (PI / 180);
472	        }
473	        else if (labelPosition === 'center') {
474	            labelRotate = 0;
475	        }
476	        else if (rotate === 'radial' || rotate === true) {
477	            const radialAngle = nx < 0 ? -midAngle + PI : -midAngle;
478	            labelRotate = radialAngle;
479	        }
480	        else if (rotate === 'tangential'
481	            && labelPosition !== 'outside' && labelPosition !== 'outer'
482	        ) {
483	            let rad = Math.atan2(nx, ny);
484	            if (rad < 0) {
485	                rad = PI * 2 + rad;
486	            }
487	            const isDown = ny > 0;
488	            if (isDown) {
489	                rad = PI + rad;
490	            }
491	            labelRotate = rad - PI;
492	        }
493	
494	        hasLabelRotate = !!labelRotate;
495	
496	        label.x = textX;
497	        label.y = textY;
498	        label.rotation = labelRotate;
499	
500	        label.setStyle({
501	            verticalAlign: 'middle'
502	        });
503	
504	        // Not sectorShape the inside label
505	        if (!isLabelInside) {
506	            const textRect = label.getBoundingRect().clone();
507	            textRect.applyTransform(label.getComputedTransform());
508	            // Text has a default 1px stroke. Exclude this.
509	            const margin = (label.style.margin || 0) + 2.1;
510	            textRect.y -= margin / 2;
511	            textRect.height += margin;
512	
513	            labelLayoutList.push({
514	                label,
515	                labelLine,
516	                position: labelPosition,
517	                len: labelLineLen,
518	                len2: labelLineLen2,
519	                minTurnAngle: labelLineModel.get('minTurnAngle'),
520	                maxSurfaceAngle: labelLineModel.get('maxSurfaceAngle'),
521	                surfaceNormal: new Point(nx, ny),
522	                linePoints: linePoints,
523	                textAlign: textAlign,
524	                labelDistance: labelDistance,
525	                labelAlignTo: labelAlignTo,
526	                edgeDistance: edgeDistance,
527	                bleedMargin: bleedMargin,
528	                rect: textRect,
529	                unconstrainedWidth: textRect.width,
530	                labelStyleWidth: label.style.width
531	            });
532	        }
533	        else {
534	            label.setStyle({
535	                align: textAlign
536	            });
537	            const selectState = label.states.select;
538	            if (selectState) {
539	                selectState.x += label.x;
540	                selectState.y += label.y;
541	            }
542	        }
543	        sector.setTextConfig({
544	            inside: isLabelInside
545	        });
546	    });
547	
548	    if (!hasLabelRotate && seriesModel.get('avoidLabelOverlap')) {
549	        avoidOverlap(labelLayoutList, cx, cy, r, viewWidth, viewHeight, viewLeft, viewTop);
550	    }
551	
552	    for (let i = 0; i < labelLayoutList.length; i++) {
553	        const layout = labelLayoutList[i];
554	        const label = layout.label;
555	        const labelLine = layout.labelLine;
556	        const notShowLabel = isNaN(label.x) || isNaN(label.y);
557	        if (label) {
558	            label.setStyle({
559	                align: layout.textAlign
560	            });
561	            if (notShowLabel) {
562	                each(label.states, setNotShow);
563	                label.ignore = true;
564	            }
565	            const selectState = label.states.select;
566	            if (selectState) {
567	                selectState.x += label.x;
568	                selectState.y += label.y;
569	            }
570	        }
571	        if (labelLine) {
572	            const linePoints = layout.linePoints;
573	            if (notShowLabel || !linePoints) {
574	                each(labelLine.states, setNotShow);
575	                labelLine.ignore = true;
576	            }
577	            else {
578	                limitTurnAngle(linePoints, layout.minTurnAngle);
579	                limitSurfaceAngle(linePoints, layout.surfaceNormal, layout.maxSurfaceAngle);
580	
581	                labelLine.setShape({ points: linePoints });
582	
583	                // Set the anchor to the midpoint of sector
584	                label.__hostTarget.textGuideLineConfig = {
585	                    anchor: new Point(linePoints[0][0], linePoints[0][1])
586	                };
587	            }
588	        }
589	    }
590	}

};

function recalculateXOnSemiToAlignOnEllipseCurve(semi: SemiInfo) {
    const rB = semi.rB;
    const rB2 = rB * rB;
    for (let i = 0; i < semi.list.length; i++) {
        const item = semi.list[i];
        const dy = Math.abs(item.label.y - cy);
        // horizontal r is always same with original r because x is not changed.
        const rA = r + item.len;
        const rA2 = rA * rA;
        // Use ellipse implicit function to calculate x
        const dx = Math.sqrt((1 - Math.abs(dy * dy / rB2)) * rA2);
